        if ( zt == null || zt == "" ) {
            zt = selectItem.getValue("EP_DOC_BASE.F_ZT", null);
        }
        if ( fbsj == null || fbsj == "" ) {
            fbsj = selectItem.getValue("EP_DOC_BASE.F_PUBDATE", null);
        }
        if (isTop == null || isTop == "") {
            isTop = selectItem.getValue("EP_DOC_BASE.F_IS_TOP", null);
        }
        if ( guid != null && guid != "" ) {
            nodeContext.setObject("djguid",guid);
	        nodeContext.setObject("openType", "Query");
        }
        if ( zt != null && zt != "" ) {
            nodeContext.setObject("zt",zt);
        }
        if ( fbsj != null && fbsj != "" ) {
            nodeContext.setObject("fbsj",fbsj);
        }
        if ( isTop != null && isTop !="") {
            nodeContext.setObject("F_IS_TOP",isTop);
        }
    }
