scriptsCode.doAction:
// (发布)GeneralAction1.doAction
// (按钮)FormButton4.onClick
debugger
var PO = new JParamObject();
var userName = PO.getEnv("UserCaption","");
var dsList = AGGrid1.getSelectedRowSetList();

var guidArr = new Array();


if (dsList != null && dsList.length > 0) {
    for(var i = 0;i<dsList.length;i++){
        var ds = dsList[i];
            var fbzt = ds.getObject("EP_DOC_BASE.F_ZT");
            var guid = ds.getObject("EP_DOC_BASE.F_GUID");

            if("7" == fbzt){
                window.showAlertMsg("发布提示", "所选公告包含已发布公告，请重新选择!", "1", "确定", null);
                //FormButton4.setDisabled(true);
                return;
            }
            guidArr.push(guid);
            var guidStr = guidArr.join(",");
            var fbzt = "7";
            var date = new Date();
            var y = date.getFullYear(); 
            var m = date.getMonth() + 1;  
            m = m < 10 ? ('0' + m) : m;  
            var d = date.getDate();  
            d = d < 10 ? ('0' + d) : d;  
            var h = date.getHours();  
            h=h < 10 ? ('0' + h) : h;  
            var minute = date.getMinutes();  
            minute = minute < 10 ? ('0' + minute) : minute;  
            var second=date.getSeconds();  
            second=second < 10 ? ('0' + second) : second;
            var fbsj = `${y}${m}${d}${h}${minute}${second}`;

            //var fbsj = y+m+d+h+minute+second;
            //var fbsj = window.getCurrentTime("yyyyMMddHHmmss"); //获取当前时间 
            var popUser = userName;

    }
    PO.setParam("flag","2");
    PO.setParam("fbzt",fbzt);
    PO.setParam("fbsj",fbsj);
    PO.setParam("xgsj",fbsj);
    PO.setParam("guidStr",guidStr);
    PO.setParam("popUser",popUser);
    PO.setParam("F_CHUSER",popUser);// 修改人
    WebService1.SVR("SYS_NOTICE_FIELDVALUEUPDATE",PO);
    // 用于标记保存后提示
    // ModelContainer1.setValue("fbzt","7");
}else{
    window.showAlertMsg("发布提示", "请选择要发布的公告!", "1", "确定", null);
}
